const el=(tag,cls,text)=>{const node=document.createElement(tag);if(cls)node.className=cls;if(text)node.textContent=text;return node;};
for(const group of window.education.groups){const card=el('article','group-card');card.append(el('h3','group-name',`${group.name}그룹`));for(const [label,date,display,weekday] of group.dates){const row=el('div','date-row');row.append(el('span','day-label',label));const time=el('time','',display);time.dateTime=date;row.append(time,el('span','weekday',weekday));card.append(row);}document.querySelector('#groups').append(card);}
window.education.days.forEach((day,index)=>{const card=el('article','day-card');card.append(el('p','day-tag',`DAY 0${index+1} · ${index+1}일차`),el('h3','',day.title));const list=el('ol','lessons');list.start=index?9:1;day.items.forEach(item=>list.append(el('li','',item)));card.append(list);document.querySelector('#days').append(card);});
